css:
.ph-stage { height: 430px; border-radius: 8px; }
.cr-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; }
.ph-stage canvas, .cr-stage canvas { touch-action: none; cursor: grab; }
.ph-stage canvas.holding, .cr-stage canvas.holding { cursor: grabbing; }
.cr-out { margin: 0; font-size: 21px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 2.2em; }
.cr-table { width: 100%; border-collapse: collapse; font-size: 19px; }
.cr-table th, .cr-table td { border: 1.5px solid var(--rule); padding: 4px 8px; text-align: center; }
.cr-table thead th { background: #eef2f7; }
.cr-table td.ok { background: var(--good-soft); color: #1f6b3d; font-weight: 800; } .cr-table td.no { background: var(--risk-soft); color: #8f2a20; font-weight: 800; }
.cr-safe { margin: 0; font-size: 17px; color: var(--ink-2); }

